for (const listener of listeners) {
      try {
        listener(event);
      } catch {
        /* a broken subscriber must not stop the rest */
      }
    }

for (const name of await fsp.readdir(dir).catch(() => [])) {
      if (!keep.has(name) && !name.endsWith('.tmp'))
        await fsp.rm(path.join(dir, name), { force: true }).catch(() => {});
    }

for (const entry of Array.isArray(tree) ? tree : []) {
    if (entry?.type !== 'blob' || typeof entry.path !== 'string') continue;
    if (!/\.kmz$/i.test(entry.path)) continue;
    if (!/^[0-9a-f]{40}$/.test(entry.sha || '')) continue;
    const size = Number(entry.size);
    if (!Number.isFinite(size) || size <= 0 || size > GHOSTMAPS_MAX_FILE_BYTES)
      continue;
    const fileName = entry.path.slice(entry.path.lastIndexOf('/') + 1);
    const candidate = {
      path: entry.path,
      fileName,
      version: entry.sha,
      size,
      ...parseGhostMapsEdition(fileName),
    };
    const product = GHOSTMAPS_PRODUCTS.find(({ pattern }) =>
      pattern.test(entry.path),
    );
    if (product) {
      if (newer(candidate, best.get(product.id)))
        best.set(product.id, candidate);
    } else if (
      entry.path.startsWith(INCIDENTS) &&
      !LATEST_DROP_EXCLUDED.test(`/${entry.path}`) &&
      candidate.dateMs != null &&
      newer(candidate, drop)
    ) {
      drop = candidate;
    }
  }

for (const product of [...GHOSTMAPS_PRODUCTS, GHOSTMAPS_LATEST_DROP]) {
    const file =
      product === GHOSTMAPS_LATEST_DROP ? drop : best.get(product.id);
    if (!file) continue;
    rows.push({
      id: product.id,
      title: product.title,
      defaultOn: product.defaultOn,
      ...file,
      fileTitle: ghostMapsFileTitle(file.fileName),
    });
  }

for (const line of String(text || '').split('\n')) {
    // pkt-line: 4 hex length digits, then "<sha> <ref>" (the first ref line
    // also carries a NUL and the capability list).
    const match = /^[0-9a-f]{4}([0-9a-f]{40}) ([^\0\s]+)/.exec(line);
    if (match && match[2] === ref) return match[1];
  }

for (const [x, y] of ring) {
    lon += x;
    lat += y;
  }

for (const id of [..._loaded.keys()]) {
        const product = products.get(id);
        if (!product || !wanted(product)) unload(id);
      }

for (const product of _catalog.products) {
        if (!wanted(product) || signal.aborted) continue;
        if (_loaded.get(product.id)?.version === product.version) continue;
        _loading.set(product.id, product.version);
        _failed.delete(product.id);
        notifyRow();
        try {
          const next = await load(product, signal);
          if (signal.aborted || !_enabled) {
            next.urls.forEach((url) => URL.revokeObjectURL(url));
            return;
          }
          // Cull before the first frame so far-side pins never flash.
          _horizon.update(next.pins);
          await _viewer.dataSources.add(next.dataSource);
          // The new edition is on the globe before the old one leaves.
          unload(product.id);
          _loaded.set(product.id, next);
        } catch (error) {
          if (signal.aborted) return;
          console.warn(`[Data:GhostMaps] ${product.id}:`, error);
          _failed.set(
            product.id,
            error?.template ||
              error?.message ||
              msg('GhostMaps file could not be read'),
          );
        } finally {
          _loading.delete(product.id);
          notifyRow();
          render();
        }
      }

for (const { label, value } of fields) {
      if (details.length >= MAX_CARD_LINES) break;
      // ArcGIS repeats the feature type as the first row; the title has it.
      if (value === feature.name) continue;
      const line = label ? `${fieldLabel(label)}: ${value}` : value;
      details.push(
        ...wrapCardText(line, 60, Math.min(4, MAX_CARD_LINES - details.length)),
      );
    }

commit
        ? _stream === 'open'
          ? t('LIVE · GitHub {commit} · {message} · checked every {seconds}s', {
              commit: commit.slice(0, 7),
              message: _catalog.message || '—',
              seconds: formatNumber(
                Math.round((_catalog.pollMs || 15000) / 1000),
              ),
            })
          : t('GitHub {commit} · {message} · reconnecting for live updates', {
              commit: commit.slice(0, 7),
              message: _catalog.message || '—',
            })
        : t('Connecting to the S2 GhostMaps repository…')

